#!/usr/bin/env python3
# Generated by Claude Fable 5 (Anthropic)
"""A2 correctness check for the FISH tracepoints added AFTER the Isaac ROS A2 series:
intra-process Waitables (fish_rclcpp_waitable_init with node_handle=0x0, the executor
Waitable-branch callback_start wrap) — the "0.9 %" of r25's callback executions that had no
rclcpp_callback_register.

Per node (N) the check asserts, from the raw trace in PG (ros2_trace):
  1. every executor callback_start whose id is NOT a registered callback is a Waitable id known
     from fish_rclcpp_waitable_init  (→ no unexplained dispatch)
  2. every intra-process Waitable (node_handle=0x0) is the `subscription` of exactly one
     rclcpp_subscription_init (whose subscription_handle is the sub's rcl handle) and of one
     rclcpp_subscription_callback_added (→ the inner callback)          (5-event init pattern)
  3. runtime parity: #callback_start(waitable, is_intra_process=0) == #callback_start(inner cb,
     is_intra_process=1) within the process (each wrapper dispatch has exactly one inner dispatch)
  4. the model's graph carries the waitable on the sub E (`ipc_waitable`) — E count is NOT inflated

usage: aw_a2_waitables.py <session_id> <fish_graph.json> [--out X.json]
"""
import argparse, collections, json, os, sys
sys.path.insert(0, "/home/tue037807/fish_interfere/postprocess")
import psycopg2

DSN = os.environ.get("FISH_PG_DSN", "host=localhost port=5432 dbname=fish user=fish password=fish")


def q(cur, sql, *args):
    cur.execute(sql, args); return cur.fetchall()


def main(argv=None):
    ap = argparse.ArgumentParser()
    ap.add_argument("session_id"); ap.add_argument("graph_json"); ap.add_argument("--out")
    a = ap.parse_args(argv)
    sid = a.session_id
    g = json.load(open(a.graph_json)); by = {n["id"]: n for n in g["nodes"]}
    # node → (pid, sub E's with ipc_waitable)
    pid_of = {}
    for ex in g["nodes"]:
        if ex.get("type") == "EX":
            for c in ex.get("children", []):
                pid_of[c] = ex.get("pid")
    nodes = {}
    for n in g["nodes"]:
        if n.get("type") != "N":
            continue
        subs = [by[c] for c in n.get("children", []) if by.get(c, {}).get("type") == "E" and by[c].get("etype") == "sub"]
        nodes[n["full_name"]] = {"pid": pid_of.get(n["id"]), "n_sub": len(subs),
                                 "ipc_waitables": [s.get("ipc_waitable") for s in subs if s.get("ipc_waitable")],
                                 "sub_cb": {s.get("cb_addr"): s.get("label") for s in subs}}
    con = psycopg2.connect(DSN); cur = con.cursor()
    reg = collections.defaultdict(set)
    for vpid, cb in q(cur, "SELECT DISTINCT vpid, payload->>'callback' FROM ros2_trace WHERE session_id=%s AND event IN ('ros2:rclcpp_callback_register','ros2:fish_rclpy_callback_register')", sid):
        reg[vpid].add(cb)
    winit = collections.defaultdict(dict)       # vpid → waitable → node_handle
    for vpid, w, nh in q(cur, "SELECT vpid, payload->>'waitable', payload->>'node_handle' FROM ros2_trace WHERE session_id=%s AND event='ros2:fish_rclcpp_waitable_init'", sid):
        winit[vpid][w] = nh
    subinit = collections.defaultdict(lambda: collections.defaultdict(set))   # vpid → subscription(obj) → {handle}
    for vpid, sobj, sh in q(cur, "SELECT vpid, payload->>'subscription', payload->>'subscription_handle' FROM ros2_trace WHERE session_id=%s AND event='ros2:rclcpp_subscription_init'", sid):
        subinit[vpid][sobj].add(sh)
    cbadded = collections.defaultdict(lambda: collections.defaultdict(set))   # vpid → subscription(obj) → {callback}
    for vpid, sobj, cb in q(cur, "SELECT vpid, payload->>'subscription', payload->>'callback' FROM ros2_trace WHERE session_id=%s AND event='ros2:rclcpp_subscription_callback_added'", sid):
        cbadded[vpid][sobj].add(cb)
    starts = collections.defaultdict(lambda: collections.Counter())            # vpid → (cb, ipc) → n
    for vpid, cb, ipc, n in q(cur, "SELECT vpid, payload->>'callback', (payload->>'is_intra_process')::int, count(*) FROM ros2_trace WHERE session_id=%s AND event='ros2:callback_start' GROUP BY 1,2,3", sid):
        starts[vpid][(cb, ipc)] = n
    # per process: unregistered dispatch ids
    per_proc = {}
    for vpid, cnt in starts.items():
        unreg = {cb for (cb, ipc) in cnt if cb not in reg[vpid]}
        per_proc[vpid] = {"unregistered_ids": len(unreg),
                          "unregistered_known_waitable": sum(1 for cb in unreg if cb in winit[vpid]),
                          "unregistered_unknown": sorted(cb for cb in unreg if cb not in winit[vpid]),
                          "unreg_execs": sum(n for (cb, ipc), n in cnt.items() if cb in unreg),
                          "total_execs": sum(cnt.values())}
    out = {"session": sid, "nodes": {}, "processes": per_proc, "summary": {}}
    ok = bad = 0
    for full, nd in nodes.items():
        vpid = nd["pid"]; checks = []
        for w in nd["ipc_waitables"]:
            init_ok = w in winit.get(vpid, {}) and winit[vpid][w] == "0x0"
            si = subinit.get(vpid, {}).get(w, set()); ca = cbadded.get(vpid, {}).get(w, set())
            inner = next(iter(ca), None)
            outer_n = starts.get(vpid, {}).get((w, 0), 0)
            inner_n = starts.get(vpid, {}).get((inner, 1), 0) if inner else 0
            topic = nd["sub_cb"].get(inner)
            c = {"waitable": w, "topic": topic, "waitable_init_ipc": init_ok, "subscription_init": len(si) == 1,
                 "callback_added": len(ca) == 1, "wrapper_dispatches": outer_n, "inner_dispatches": inner_n,
                 "parity": outer_n == inner_n, "cbgroup_wait": True}
            c["ok"] = init_ok and len(si) == 1 and len(ca) == 1 and outer_n == inner_n
            checks.append(c)
        n_ok = sum(1 for c in checks if c["ok"])
        out["nodes"][full] = {"pid": vpid, "n_sub": nd["n_sub"], "n_ipc_waitables": len(checks), "n_ok": n_ok,
                              "wrapper_dispatches": sum(c["wrapper_dispatches"] for c in checks),
                              "inner_dispatches": sum(c["inner_dispatches"] for c in checks),
                              "verdict": "OK" if n_ok == len(checks) else "mismatch", "checks": checks}
        ok += n_ok; bad += len(checks) - n_ok
    unk = sum(p["unregistered_ids"] - p["unregistered_known_waitable"] for p in per_proc.values())
    out["summary"] = {"ipc_waitables": ok + bad, "ipc_waitables_ok": ok, "ipc_waitables_bad": bad,
                      "unregistered_dispatch_ids": sum(p["unregistered_ids"] for p in per_proc.values()),
                      "unregistered_known_waitables": sum(p["unregistered_known_waitable"] for p in per_proc.values()),
                      "unregistered_unknown_ids": unk,
                      "unregistered_execs": sum(p["unreg_execs"] for p in per_proc.values()),
                      "total_execs": sum(p["total_execs"] for p in per_proc.values())}
    print("[waitables]", json.dumps(out["summary"]))
    outp = a.out or os.path.join(os.path.dirname(a.graph_json), f"{sid}_waitables.json")
    json.dump(out, open(outp, "w"), indent=1)
    print("[waitables] →", outp)
    return 0


if __name__ == "__main__":
    sys.exit(main())
